"use client"

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Los campos sensibles llegan enmascarados. Mostrar llama onReveal con el id.
 */

import { useState } from "react"
import { Download } from "lucide-react"

import { cn } from "@/lib/utils"
import { deskInitials } from "@/lib/inbox"
import type { PartyDeal, PartyFact, PartyFile, PartyMember, SecretField } from "@/lib/thread-desk"

export type PartyAction = {
  id: string
  label: string
  onSelect?: () => void
}

export type PartyPanelProps = {
  name?: string
  meta?: string
  actions?: readonly PartyAction[]
  deal?: PartyDeal
  facts?: readonly PartyFact[]
  members?: readonly PartyMember[]
  files?: readonly PartyFile[]
  secrets?: readonly SecretField[]
  revealLabel?: string
  onReveal?: (id: string) => void
  onDownload?: (id: string) => void
  downloadLabel?: string
  membersLabel?: string
  filesLabel?: string
  state?: "ready" | "loading" | "empty" | "error"
  emptyLabel?: string
  loadingLabel?: string
  error?: string
  className?: string
}

function SecretRow({ field, revealLabel, onReveal }: { field: SecretField; revealLabel: string; onReveal?: (id: string) => void }) {
  const [open, setOpen] = useState(false)
  return (
    <div className="flex items-center justify-between gap-2 py-2">
      <span className="min-w-0">
        <span className="block text-xs text-muted-foreground">{field.label}</span>
        <span className="block text-sm tabular-nums" data-revealed={open ? "true" : "false"}>
          {open ? field.revealed : field.masked}
        </span>
      </span>
      <button
        type="button"
        className="h-11 shrink-0 rounded-full px-3 text-sm font-medium text-primary focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
        onClick={() => {
          if (open) return
          setOpen(true)
          onReveal?.(field.id)
        }}
      >
        {revealLabel}
      </button>
    </div>
  )
}

export function PartyPanel({
  name,
  meta,
  actions = [],
  deal,
  facts = [],
  members = [],
  files = [],
  secrets = [],
  revealLabel = "Mostrar",
  onReveal,
  onDownload,
  downloadLabel = "Descargar",
  membersLabel = "Miembros",
  filesLabel = "Archivos",
  state = "ready",
  emptyLabel = "Sin ficha",
  loadingLabel = "Cargando la ficha",
  error,
  className,
}: PartyPanelProps) {
  if (state === "loading") return <div role="status" aria-label={loadingLabel} className="h-48 animate-pulse rounded-2xl bg-muted" />
  if (state === "error") {
    return (
      <p role="alert" className="text-sm text-destructive">
        {error}
      </p>
    )
  }
  if (state === "empty" || !name) {
    return (
      <p role="status" className="text-sm text-muted-foreground">
        {emptyLabel}
      </p>
    )
  }
  return (
    <aside data-slot="party-panel" className={cn("flex flex-col gap-5", className)}>
      <div className="grid justify-items-center gap-2 text-center">
        <span className="grid size-16 place-items-center rounded-full bg-foreground text-lg font-semibold text-background" aria-hidden>
          {deskInitials(name)}
        </span>
        <h2 className="text-base font-semibold">{name}</h2>
        {meta ? <p className="text-xs text-muted-foreground">{meta}</p> : null}
      </div>
      {actions.length ? (
        <div className="grid grid-cols-3 gap-2">
          {actions.map((action) => (
            <button
              key={action.id}
              type="button"
              className="grid h-16 place-items-center rounded-2xl bg-muted px-2 text-center text-xs font-medium focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
              onClick={action.onSelect}
            >
              {action.label}
            </button>
          ))}
        </div>
      ) : null}
      {deal ? (
        <section className="grid gap-2 rounded-2xl bg-muted/60 p-3">
          <div className="flex items-center justify-between gap-2">
            <h3 className="text-sm font-medium">{deal.title}</h3>
            <span className="text-xs text-muted-foreground">{deal.status}</span>
          </div>
          <p className="text-sm tabular-nums">{deal.amount}</p>
          <div
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={deal.value}
            aria-label={deal.label}
            className="h-2 overflow-hidden rounded-full bg-background"
          >
            <div className="h-full rounded-full bg-primary" style={{ width: `${Math.max(0, Math.min(100, deal.value))}%` }} />
          </div>
          <p className="text-end text-xs text-muted-foreground tabular-nums">{deal.label}</p>
        </section>
      ) : null}
      {facts.length ? (
        <dl className="grid gap-3">
          {facts.map((fact) => (
            <div key={fact.id} className="flex items-baseline justify-between gap-3">
              <dt className="text-xs text-muted-foreground">{fact.label}</dt>
              <dd className="text-sm font-medium">{fact.value}</dd>
            </div>
          ))}
        </dl>
      ) : null}
      {secrets.length ? (
        <div className="divide-y divide-border border-y border-border">
          {secrets.map((field) => (
            <SecretRow key={field.id} field={field} revealLabel={revealLabel} onReveal={onReveal} />
          ))}
        </div>
      ) : null}
      {members.length ? (
        <section className="grid gap-2">
          <h3 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">{membersLabel}</h3>
          <ul className="grid gap-2">
            {members.map((member) => (
              <li key={member.id} className="flex min-h-11 items-center gap-2">
                <span className="grid size-8 place-items-center rounded-full bg-muted text-[10px] font-medium" aria-hidden>
                  {deskInitials(member.name)}
                </span>
                <span className="min-w-0">
                  <span className="block truncate text-sm font-medium">{member.name}</span>
                  <span className="block truncate text-xs text-muted-foreground">{member.role}</span>
                </span>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
      {files.length ? (
        <section className="grid gap-2">
          <h3 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">{filesLabel}</h3>
          <ul className="grid gap-2">
            {files.map((file) => (
              <li key={file.id} className="flex min-h-11 items-center gap-2">
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-medium">{file.name}</span>
                  <span className="block truncate text-xs text-muted-foreground">{file.detail}</span>
                </span>
                <button
                  type="button"
                  aria-label={`${downloadLabel} ${file.name}`}
                  className="grid size-11 place-items-center rounded-full hover:bg-muted focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none"
                  onClick={() => onDownload?.(file.id)}
                >
                  <Download className="size-4" aria-hidden />
                </button>
              </li>
            ))}
          </ul>
        </section>
      ) : null}
    </aside>
  )
}

/**
 * Bandeja de conversaciones.
 * Fuente: concepto visual de Divan Raj (@desdivj),
 * https://x.com/desdivj/status/2119738295039250507
 * Licencia: sin licencia, clean-room. No se copiaron assets, logos,
 * ilustraciones ni textos.
 * Tipos y puertos. Sin red, sin Supabase y sin dominio de un canal.
 */

import type { ReactNode } from "react"

import { foldInboxText, type DeskPresence } from "@/lib/inbox"

export type ThreadStatus = "ready" | "loading" | "empty" | "error" | "offline"

export type ThreadFilter = {
  value: string
  label: string
}

export type ConversationSection = {
  id: string
  label: string
  hint?: string
}

export type ConversationItemData = {
  id: string
  title: string
  preview?: string
  time?: string
  unread?: number
  section?: string
  tags?: readonly string[]
  presence?: DeskPresence
  role?: string
  kind?: "thread" | "contact"
  stage?: string
  windowLabel?: string
  channel?: ReactNode
}

export type DeliveryState = "sending" | "sent" | "delivered" | "read" | "failed"

export type ThreadNote = {
  title: string
  detail: string
  body?: string
}

export type ThreadFile = {
  name: string
  detail: string
  status?: string
}

export type ThreadInvoice = {
  title: string
  amount: string
  due: string
}

export type ThreadMetric = {
  title: string
  chip?: string
  value: string
  caption?: string
  filled: number
  total: number
  start: string
  end: string
}

export type ThreadMessageData = {
  id: string
  side: "incoming" | "outgoing"
  author: string
  time?: string
  body?: string
  delivery?: DeliveryState
  deliveryLabel?: string
  grouped?: "single" | "start" | "middle" | "end"
  enter?: boolean
  note?: ThreadNote
  file?: ThreadFile
  invoice?: ThreadInvoice
  metric?: ThreadMetric
}

export type SuggestionItem = {
  id: string
  label: string
}

export type SecretField = {
  id: string
  label: string
  masked: string
  revealed: string
}

export type PartyFact = {
  id: string
  label: string
  value: string
}

export type PartyMember = {
  id: string
  name: string
  role: string
}

export type PartyFile = {
  id: string
  name: string
  detail: string
}

export type PartyDeal = {
  title: string
  status: string
  amount: string
  value: number
  label: string
}

export type PartyPanelData = {
  name: string
  meta?: string
  deal?: PartyDeal
  facts?: readonly PartyFact[]
  members?: readonly PartyMember[]
  files?: readonly PartyFile[]
  secrets?: readonly SecretField[]
}

export function matchesConversation(item: ConversationItemData, filter: string | undefined, query: string) {
  if (filter && filter !== "all") {
    const tagged = item.tags?.includes(filter) || (filter === "unread" && (item.unread ?? 0) > 0)
    if (!tagged) return false
  }
  const needle = query.trim()
  if (!needle) return true
  const hay = [item.title, item.preview, item.role, item.stage, item.windowLabel].filter(Boolean).join(" ")
  return foldInboxText(hay).includes(foldInboxText(needle))
}

export function groupMessages(messages: readonly ThreadMessageData[]): ThreadMessageData[] {
  return messages.map((message, index) => {
    if (message.grouped) return message
    const prev = messages[index - 1]
    const next = messages[index + 1]
    const same = (other?: ThreadMessageData) =>
      Boolean(other && other.side === message.side && other.author === message.author && !other.file && !other.invoice && !other.metric && !message.file && !message.invoice && !message.metric)
    const before = same(prev)
    const after = same(next)
    const grouped = before && after ? "middle" : before ? "end" : after ? "start" : "single"
    return { ...message, grouped }
  })
}

/**
 * Shared types for the desk pieces. No fetching, no theme.
 * Dates are calendar days (`YYYY-MM-DD`). The host owns locale and timezone.
 */

export const DESK_PRESENCES = ["online", "offline", "away"] as const

export type DeskPresence = (typeof DESK_PRESENCES)[number]

export type DeskMessage = {
  id: string
  author: string
  body: string
  /** Preformatted time. */
  time: string
  side: "incoming" | "outgoing"
  note?: boolean
  receipt?: "seen" | "unseen"
}

export type DeskOption = {
  value: string
  label: string
}

const DATE_RE = /^(\d{4})-(\d{2})-(\d{2})$/

export function foldInboxText(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase()
}

export function isCalendarDate(value: string | undefined): value is string {
  return Boolean(value && DATE_RE.test(value))
}

/** True when `due` is a calendar day before `today`. */
export function isOverdueDate(due: string | undefined, today: string): boolean {
  if (!isCalendarDate(due) || !isCalendarDate(today)) return false
  return due < today
}

export function formatDeskDate(iso: string, locale?: string): string {
  if (!isCalendarDate(iso)) return iso
  const [year, month, day] = iso.split("-").map(Number)
  return new Intl.DateTimeFormat(locale, { dateStyle: "medium", timeZone: "UTC" }).format(
    new Date(Date.UTC(year, month - 1, day)),
  )
}

export function deskInitials(name: string): string {
  const letters = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase() ?? "")
    .join("")
  return letters || "?"
}
